tool_schemas.implementation:
def list_emails(workspace_id, identity_id, label=None, is_read=None, is_trashed=None, is_archived=None, since=None, until=None, limit=None, cursor=None, sort=None, include_raw=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt): return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _parse_dt(s, field):
        if s is None: return None, None
        if not isinstance(s, str): return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
        try:
            ss = s.strip()
            if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string")
    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}:{now.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper()

    tool_name = "list_emails"
    tool_calls = _load("tool_calls.json")
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    messages = _load("gmail_messages.json")

    # Pre-validate types/enums/ranges
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is required and must match ^gws_ws_[0-9A-Z]+$")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id):
        return _err("VALIDATION_ERROR", "identity_id is required and must match ^gws_gid_[0-9A-Z]+$")
    if label is not None and not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label must be a string")
    for bname, bval in [("is_read", is_read), ("is_trashed", is_trashed), ("is_archived", is_archived), ("include_raw", include_raw)]:
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "internal_date_desc"
    if sort not in ("internal_date_desc", "internal_date_asc"):
        return _err("VALIDATION_ERROR", "sort must be one of: internal_date_desc, internal_date_asc")
    since_dt, e = _parse_dt(since, "since")
    if e: return e
    until_dt, e = _parse_dt(until, "until")
    if e: return e
    if since_dt and until_dt and until_dt < since_dt:
        return _err("VALIDATION_ERROR", "until must be >= since")

    # Resolve workspace + identity
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "workspace is not active")
    gid = next((g for g in identities if g.get("id") == identity_id and g.get("workspace_id") == workspace_id), None)
    if not gid:
        return _err("NOT_FOUND", "identity not found in workspace")

    # Quota enforcement (per UTC day) against completed calls
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    completed_today = 0
    for c in tool_calls:
        if c.get("workspace_id") != workspace_id: 
            continue
        if c.get("status") not in ("succeeded", "failed"):
            continue
        try:
            ca = c.get("created_at")
            if isinstance(ca, str):
                ss = ca.strip()
                if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
                cdt = datetime.datetime.fromisoformat(ss)
                if cdt.tzinfo is None:
                    cdt = cdt.replace(tzinfo=datetime.timezone.utc)
                cdt = cdt.astimezone(datetime.timezone.utc)
                if cdt >= day_start:
                    completed_today += 1
        except Exception:
            pass
    quota = ws.get("daily_tool_call_quota")
    if isinstance(quota, int) and quota >= 0 and completed_today >= quota:
        # Must still record tool call (rejected before contacting Google); status failed, rate/quota error
        call_id = _new_id("gws_tc")
        tc = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": tool_name,
            "request_params": {
                "label": label, "is_read": is_read, "is_trashed": is_trashed, "is_archived": is_archived,
                "since": since, "until": until, "limit": limit, "cursor": cursor, "sort": sort, "include_raw": include_raw
            },
            "idempotency_key": None,
            "status": "failed",
            "http_status": 429,
            "error_code": "quota_exceeded",
            "error_message": "Daily tool call quota exceeded for workspace",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return _err("QUOTA_EXCEEDED", "Daily tool call quota exceeded")

    # Create tool call audit row (running -> succeeded/failed)
    call_id = _new_id("gws_tc")
    tc = {
        "id": call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": tool_name,
        "request_params": {
            "label": label, "is_read": is_read, "is_trashed": is_trashed, "is_archived": is_archived,
            "since": since, "until": until, "limit": limit, "cursor": cursor, "sort": sort, "include_raw": include_raw
        },
        "idempotency_key": None,
        "status": "running",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_calls.append(tc)
    _save("tool_calls.json", tool_calls)

    # Identity state check for Google access (Gmail tool)
    if gid.get("status") != "active":
        err_code = "needs_reauth" if gid.get("status") == "needs_reauth" else "revoked"
        tc["status"] = "failed"
        tc["http_status"] = 401
        tc["error_code"] = err_code
        tc["error_message"] = "Google identity not active"
        tc["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        tc["updated_at"] = tc["finished_at"]
        _save("tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "Google identity not active", reason=err_code)

    # Cache staleness / retention check; offline "refresh" simulated by touching last_synced_at
    retention_days = ws.get("retention_days")
    if not isinstance(retention_days, int) or retention_days < 1 or retention_days > 3650:
        retention_days = 30
    stale_before = now - datetime.timedelta(days=retention_days)

    # If no messages or any message last_synced_at missing/old, simulate a "fetch" by updating last_synced_at.
    # (We cannot call Google offline; we still follow the rule by upserting/refreshing existing rows.)
    touched = []
    changed = False
    identity_msgs = [m for m in messages if m.get("workspace_id") == workspace_id and m.get("identity_id") == identity_id and m.get("status") == "active"]
    need_refresh = False
    if len(identity_msgs) == 0:
        need_refresh = True
    else:
        for m in identity_msgs:
            lsa = m.get("last_synced_at")
            if not isinstance(lsa, str):
                need_refresh = True
                break
            try:
                ss = lsa.strip()
                if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
                if dt < stale_before:
                    need_refresh = True
                    break
            except Exception:
                need_refresh = True
                break
    if need_refresh and len(identity_msgs) > 0:
        # refresh existing cache rows timestamps
        for m in identity_msgs:
            m["last_synced_at"] = _iso(now)
            m["updated_at"] = _iso(now)
            touched.append(m.get("id"))
        changed = True

    # Filter
    filtered = []
    for m in identity_msgs:
        if label is not None:
            labs = m.get("labels") or []
            if not isinstance(labs, list) or label not in labs:
                continue
        if is_read is not None and bool(m.get("is_read")) != is_read:
            continue
        if is_trashed is not None and bool(m.get("is_trashed")) != is_trashed:
            continue
        if is_archived is not None and bool(m.get("is_archived")) != is_archived:
            continue
        idate = m.get("internal_date")
        if since_dt or until_dt:
            if not isinstance(idate, str):
                continue
            try:
                ss = idate.strip()
                if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except Exception:
                continue
            if since_dt and dt < since_dt:
                continue
            if until_dt and dt > until_dt:
                continue
        filtered.append(m)

    # Sort
    def _sort_key(m):
        idate = m.get("internal_date")
        if isinstance(idate, str):
            try:
                ss = idate.strip()
                if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    reverse = (sort == "internal_date_desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    # Pagination cursor is base64url encoded integer offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            offset = int(raw)
            if offset < 0: offset = 0
        except Exception:
            # invalid cursor => validation error
            tc["status"] = "failed"
            tc["http_status"] = 400
            tc["error_code"] = "validation_error"
            tc["error_message"] = "Invalid cursor"
            tc["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            tc["updated_at"] = tc["finished_at"]
            _save("tool_calls.json", tool_calls)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    # Shape items
    items = []
    for m in page:
        item = {
            "id": m.get("id"),
            "workspace_id": m.get("workspace_id"),
            "identity_id": m.get("identity_id"),
            "gmail_message_id": m.get("gmail_message_id"),
            "gmail_thread_id": m.get("gmail_thread_id"),
            "rfc822_message_id": m.get("rfc822_message_id"),
            "subject": m.get("subject"),
            "from": m.get("from"),
            "to": m.get("to"),
            "cc": m.get("cc"),
            "snippet": m.get("snippet"),
            "internal_date": m.get("internal_date"),
            "labels": m.get("labels"),
            "is_read": m.get("is_read"),
            "is_trashed": m.get("is_trashed"),
            "is_archived": m.get("is_archived"),
            "last_synced_at": m.get("last_synced_at"),
            "created_at": m.get("created_at"),
            "updated_at": m.get("updated_at"),
        }
        if include_raw:
            item["raw_mime_b64"] = m.get("raw_mime_b64")
        items.append(item)
        touched.append(m.get("id"))

    # Persist refresh changes if any
    if changed:
        _save("gmail_messages.json", messages)

    # Finish tool call
    tc["status"] = "succeeded"
    tc["http_status"] = 200
    tc["result_summary"] = {"returned": len(items), "total_matched": len(filtered), "has_more": has_more}
    tc["touched_gmail_message_ids"] = list(dict.fromkeys([x for x in touched if isinstance(x, str)])) or []
    tc["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    tc["updated_at"] = tc["finished_at"]
    _save("tool_calls.json", tool_calls)

    return {
        "messages": items,
        "meta": {"total": len(filtered), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

def search_emails(workspace_id, identity_id, query, limit=None, cursor=None, sort=None, include_raw=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt): return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}:{now.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:18].upper()

    tool_name = "search_emails"
    tool_calls = _load("tool_calls.json")
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    messages = _load("gmail_messages.json")

    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is required and must match ^gws_ws_[0-9A-Z]+$")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id):
        return _err("VALIDATION_ERROR", "identity_id is required and must match ^gws_gid_[0-9A-Z]+$")
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "internal_date_desc"
    if sort not in ("internal_date_desc", "internal_date_asc"):
        return _err("VALIDATION_ERROR", "sort must be one of: internal_date_desc, internal_date_asc")
    if include_raw is not None and not isinstance(include_raw, bool):
        return _err("VALIDATION_ERROR", "include_raw must be a boolean")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "workspace is not active")
    gid = next((g for g in identities if g.get("id") == identity_id and g.get("workspace_id") == workspace_id), None)
    if not gid:
        return _err("NOT_FOUND", "identity not found in workspace")

    # Quota enforcement
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    completed_today = 0
    for c in tool_calls:
        if c.get("workspace_id") != workspace_id:
            continue
        if c.get("status") not in ("succeeded", "failed"):
            continue
        try:
            ca = c.get("created_at")
            if isinstance(ca, str):
                ss = ca.strip()
                if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
                cdt = datetime.datetime.fromisoformat(ss)
                if cdt.tzinfo is None:
                    cdt = cdt.replace(tzinfo=datetime.timezone.utc)
                cdt = cdt.astimezone(datetime.timezone.utc)
                if cdt >= day_start:
                    completed_today += 1
        except Exception:
            pass
    quota = ws.get("daily_tool_call_quota")
    if isinstance(quota, int) and quota >= 0 and completed_today >= quota:
        call_id = _new_id("gws_tc")
        tc = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": tool_name,
            "request_params": {"query": query, "limit": limit, "cursor": cursor, "sort": sort, "include_raw": include_raw},
            "idempotency_key": None,
            "status": "failed",
            "http_status": 429,
            "error_code": "quota_exceeded",
            "error_message": "Daily tool call quota exceeded for workspace",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return _err("QUOTA_EXCEEDED", "Daily tool call quota exceeded")

    # Audit row
    call_id = _new_id("gws_tc")
    tc = {
        "id": call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": tool_name,
        "request_params": {"query": query, "limit": limit, "cursor": cursor, "sort": sort, "include_raw": include_raw},
        "idempotency_key": None,
        "status": "running",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    tool_calls.append(tc)
    _save("tool_calls.json", tool_calls)

    if gid.get("status") != "active":
        err_code = "needs_reauth" if gid.get("status") == "needs_reauth" else "revoked"
        tc["status"] = "failed"
        tc["http_status"] = 401
        tc["error_code"] = err_code
        tc["error_message"] = "Google identity not active"
        tc["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        tc["updated_at"] = tc["finished_at"]
        _save("tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "Google identity not active", reason=err_code)

    # "Search" is applied over cache; if cache appears empty, treat coverage as insufficient and (offline) do no-op refresh.
    identity_msgs = [m for m in messages if m.get("workspace_id") == workspace_id and m.get("identity_id") == identity_id and m.get("status") == "active"]
    touched = []
    if len(identity_msgs) == 0:
        # insufficient coverage would trigger Gmail query; offline cannot, but still succeed with empty list.
        pass

    q = query.strip()

    # Minimal Gmail query parsing:
    # supports tokens: from:<substr>, to:<substr>, subject:<substr>, label:<LABEL>, has:attachment (ignored), is:unread/read, in:trash/in:inbox
    tokens = [t for t in re.split(r"\s+", q) if t]
    clauses = {"from": [], "to": [], "subject": [], "label": [], "is": [], "in": []}
    free_terms = []
    for t in tokens:
        m = re.match(r"^(from|to|subject|label|is|in):(.+)$", t, flags=re.IGNORECASE)
        if m:
            k = m.group(1).lower()
            v = m.group(2).strip()
            clauses.setdefault(k, []).append(v)
        else:
            free_terms.append(t)

    def _match(m):
        # from
        f = (m.get("from") or "")
        for v in clauses["from"]:
            if v.lower() not in f.lower():
                return False
        # to
        to_list = m.get("to") or []
        if not isinstance(to_list, list): to_list = []
        to_str = " ".join([str(x) for x in to_list])
        for v in clauses["to"]:
            if v.lower() not in to_str.lower():
                return False
        # subject
        subj = (m.get("subject") or "")
        for v in clauses["subject"]:
            if v.lower() not in subj.lower():
                return False
        # label
        labs = m.get("labels") or []
        if not isinstance(labs, list): labs = []
        for v in clauses["label"]:
            if v not in labs:
                return False
        # is
        for v in clauses["is"]:
            vv = v.lower()
            if vv == "unread" and bool(m.get("is_read")):
                return False
            if vv == "read" and not bool(m.get("is_read")):
                return False
        # in
        for v in clauses["in"]:
            vv = v.lower()
            if vv == "trash" and not bool(m.get("is_trashed")):
                return False
            if vv == "inbox":
                labs2 = m.get("labels") or []
                if not isinstance(labs2, list) or "INBOX" not in labs2:
                    return False
        # free terms against subject/snippet/from
        hay = " ".join([(m.get("subject") or ""), (m.get("snippet") or ""), (m.get("from") or "")]).lower()
        for term in free_terms:
            if term.lower() not in hay:
                return False
        return True

    matched = [m for m in identity_msgs if _match(m)]

    # sort by internal_date
    def _sort_key(m):
        idate = m.get("internal_date")
        if isinstance(idate, str):
            try:
                ss = idate.strip()
                if ss.endswith("Z"): ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except Exception:
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    reverse = (sort == "internal_date_desc")
    matched.sort(key=_sort_key, reverse=reverse)

    # pagination cursor: offset
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            offset = int(raw)
            if offset < 0: offset = 0
        except Exception:
            tc["status"] = "failed"
            tc["http_status"] = 400
            tc["error_code"] = "validation_error"
            tc["error_message"] = "Invalid cursor"
            tc["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            tc["updated_at"] = tc["finished_at"]
            _save("tool_calls.json", tool_calls)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    page = matched[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(matched)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    items = []
    for m in page:
        item = {
            "id": m.get("id"),
            "workspace_id": m.get("workspace_id"),
            "identity_id": m.get("identity_id"),
            "gmail_message_id": m.get("gmail_message_id"),
            "gmail_thread_id": m.get("gmail_thread_id"),
            "rfc822_message_id": m.get("rfc822_message_id"),
            "subject": m.get("subject"),
            "from": m.get("from"),
            "to": m.get("to"),
            "cc": m.get("cc"),
            "snippet": m.get("snippet"),
            "internal_date": m.get("internal_date"),
            "labels": m.get("labels"),
            "is_read": m.get("is_read"),
            "is_trashed": m.get("is_trashed"),
            "is_archived": m.get("is_archived"),
            "last_synced_at": m.get("last_synced_at"),
            "created_at": m.get("created_at"),
            "updated_at": m.get("updated_at"),
        }
        if include_raw:
            item["raw_mime_b64"] = m.get("raw_mime_b64")
        items.append(item)
        touched.append(m.get("id"))

    tc["status"] = "succeeded"
    tc["http_status"] = 200
    tc["result_summary"] = {"returned": len(items), "total_matched": len(matched), "has_more": has_more}
    tc["touched_gmail_message_ids"] = list(dict.fromkeys([x for x in touched if isinstance(x, str)])) or []
    tc["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    tc["updated_at"] = tc["finished_at"]
    _save("tool_calls.json", tool_calls)

    return {"messages": items, "meta": {"total": len(matched), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def modify_email(workspace_id, identity_id, message_id=None, gmail_message_id=None, action=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "modify_email"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_str(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _new_id(prefix):
        n = _now()
        seed = f"{prefix}:{n.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:18].upper()}"

    def _count_day_used(tool_calls_rows, ws_id, day_str):
        used = 0
        for r in tool_calls_rows:
            if r.get("workspace_id") != ws_id:
                continue
            if r.get("status") not in ("succeeded", "failed"):
                continue
            t = _parse_dt(r.get("created_at")) or _parse_dt(r.get("finished_at")) or _parse_dt(r.get("started_at")) or _parse_dt(r.get("updated_at"))
            if t and _utc_day_str(t) == day_str:
                used += 1
        return used

    def _find_tool_call_by_idem(tool_calls_rows, ws_id, tool, idem_key):
        if not idem_key:
            return None
        for r in tool_calls_rows:
            if r.get("workspace_id") == ws_id and r.get("tool_name") == tool and r.get("idempotency_key") == idem_key:
                return r
        return None

    def _append_tool_call(tool_calls_rows, row):
        tool_calls_rows.append(row)
        _save("tool_calls.json", tool_calls_rows)

    def _update_tool_call(tool_calls_rows, call_id, **updates):
        for r in tool_calls_rows:
            if r.get("id") == call_id:
                r.update(updates)
                r["updated_at"] = _iso(_now())
                _save("tool_calls.json", tool_calls_rows)
                return r
        _save("tool_calls.json", tool_calls_rows)
        return None

    # -------------------- Validate inputs --------------------
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must be a string matching ^gws_ws_[0-9A-Z]+$")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id or ""):
        return _err("VALIDATION_ERROR", "identity_id must be a string matching ^gws_gid_[0-9A-Z]+$")

    allowed_actions = {"archive", "unarchive", "trash", "untrash", "mark_read", "mark_unread"}
    if not isinstance(action, str) or action not in allowed_actions:
        return _err("VALIDATION_ERROR", f"action must be one of {sorted(allowed_actions)}")

    # Vendor schema says oneOf; enforce: exactly one identifier.
    if (message_id is None and gmail_message_id is None) or (message_id is not None and gmail_message_id is not None):
        return _err("VALIDATION_ERROR", "Provide exactly one of message_id or gmail_message_id (not both).")

    if message_id is not None:
        if not isinstance(message_id, str) or not re.match(r"^gws_msg_[0-9A-Z]+$", message_id or ""):
            return _err("VALIDATION_ERROR", "message_id must be a string matching ^gws_msg_[0-9A-Z]+$")
    if gmail_message_id is not None:
        if not isinstance(gmail_message_id, str) or not gmail_message_id.strip():
            return _err("VALIDATION_ERROR", "gmail_message_id must be a non-empty string")

    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")

    # -------------------- Load state --------------------
    ws_rows = _load("workspaces.json")
    gid_rows = _load("google_identities.json")
    msg_rows = _load("gmail_messages.json")
    tool_calls_rows = _load("tool_calls.json")

    ws = next((w for w in ws_rows if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", f"Workspace is not active (status={ws.get('status')})")

    # Identity must exist and belong to workspace.
    identity = next((g for g in gid_rows if g.get("id") == identity_id and g.get("workspace_id") == workspace_id), None)
    if not identity:
        # Important: say which rule. Also prevents rejecting valid request merely due to a bad id; here it's truly missing.
        return _err("NOT_FOUND", "Identity not found for this workspace (FK: google_identities.workspace_id must match)")

    # -------------------- Quota enforcement (before contacting/upstream; here still enforce) --------------------
    # This tool counts as a call even if it fails; but must be rejected if quota exceeded.
    now = _now()
    day_str = _utc_day_str(now)
    quota = ws.get("daily_tool_call_quota")
    if not isinstance(quota, int) or quota < 0:
        quota = 0
    used = _count_day_used(tool_calls_rows, workspace_id, day_str)
    if quota == 0 or used >= quota:
        # Must still log the rejected call as failed (observability), but rejection is "before contacting Google".
        call_id = _new_id("gws_call")
        call_row = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": tool_name,
            "request_params": {
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                "message_id": message_id,
                "gmail_message_id": gmail_message_id,
                "action": action,
                "idempotency_key": idempotency_key,
            },
            "idempotency_key": idempotency_key,
            "status": "failed",
            "http_status": 429,
            "error_code": "quota_exceeded",
            "error_message": "Workspace daily_tool_call_quota exceeded for UTC day",
            "result_summary": {"quota": quota, "used": used},
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_tool_call(tool_calls_rows, call_row)
        return _err("QUOTA_EXCEEDED", "Workspace daily_tool_call_quota exceeded", quota=quota, used=used)

    # -------------------- Idempotency --------------------
    if idempotency_key:
        prior = _find_tool_call_by_idem(tool_calls_rows, workspace_id, tool_name, idempotency_key)
        if prior:
            # Return prior result summary if succeeded; if failed, return same failure shape.
            if prior.get("status") == "succeeded":
                return {
                    "workspace_id": workspace_id,
                    "identity_id": identity_id,
                    "message": prior.get("result_summary", {}).get("message"),
                    "updated_message": prior.get("result_summary", {}).get("updated_message"),
                    "tool_call_id": prior.get("id"),
                    "idempotency_key": idempotency_key,
                }
            return _err(
                "CONFLICT",
                "A prior modify_email call with this idempotency_key did not succeed; refusing to re-apply.",
                tool_call_id=prior.get("id"),
                prior_status=prior.get("status"),
                error_code=prior.get("error_code"),
                error_message=prior.get("error_message"),
            )

    # -------------------- Create tool_call row (received->running->succeeded/failed) --------------------
    call_id = _new_id("gws_call")
    call_row = {
        "id": call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": tool_name,
        "request_params": {
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "message_id": message_id,
            "gmail_message_id": gmail_message_id,
            "action": action,
            "idempotency_key": idempotency_key,
        },
        "idempotency_key": idempotency_key,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _append_tool_call(tool_calls_rows, call_row)

    _update_tool_call(tool_calls_rows, call_id, status="running", started_at=_iso(_now()))

    # -------------------- Identity status business rule --------------------
    # For tools requiring Google API access: must fail if identity not active.
    # modify_email is a Gmail tool; enforce.
    if identity.get("status") != "active":
        code = "needs_reauth" if identity.get("status") == "needs_reauth" else ("revoked" if identity.get("status") == "revoked" else "invalid_identity_state")
        msg = f"Identity status is {identity.get('status')}; Gmail access requires status='active'"
        _update_tool_call(
            tool_calls_rows,
            call_id,
            status="failed",
            http_status=401,
            error_code=code,
            error_message=msg,
            finished_at=_iso(_now()),
            result_summary={"message": msg},
        )
        return _err("UNAUTHORIZED", msg, identity_status=identity.get("status"))

    # -------------------- Find target message --------------------
    target = None
    if message_id is not None:
        target = next((m for m in msg_rows if m.get("id") == message_id and m.get("workspace_id") == workspace_id and m.get("identity_id") == identity_id), None)
    else:
        target = next((m for m in msg_rows if m.get("gmail_message_id") == gmail_message_id and m.get("workspace_id") == workspace_id and m.get("identity_id") == identity_id), None)

    if not target or target.get("status") == "deleted":
        emsg = "Gmail message not found in cache for this identity/workspace"
        _update_tool_call(
            tool_calls_rows,
            call_id,
            status="failed",
            http_status=404,
            error_code="not_found",
            error_message=emsg,
            finished_at=_iso(_now()),
            result_summary={"message": emsg},
            touched_gmail_message_ids=[],
        )
        return _err("NOT_FOUND", emsg)

    # -------------------- Apply Gmail semantics --------------------
    labels = target.get("labels")
    if labels is None:
        labels = []
    if not isinstance(labels, list):
        labels = list(labels) if isinstance(labels, tuple) else []
    labels = [str(x) for x in labels if isinstance(x, (str, int, float, bool))]

    def _dedupe(seq):
        seen = set()
        out = []
        for x in seq:
            if x not in seen:
                seen.add(x)
                out.append(x)
        return out

    def _remove(lbl):
        nonlocal labels
        labels = [x for x in labels if x != lbl]

    def _add(lbl):
        nonlocal labels
        if lbl not in labels:
            labels.append(lbl)

    # Actions:
    if action == "mark_read":
        _remove("UNREAD")
    elif action == "mark_unread":
        _add("UNREAD")
    elif action == "trash":
        _add("TRASH")
        _remove("INBOX")
    elif action == "untrash":
        _remove("TRASH")
        # Do not force INBOX; Gmail doesn't necessarily restore to INBOX automatically.
    elif action == "archive":
        _remove("INBOX")
        # Must not add TRASH.
    elif action == "unarchive":
        # Put back in INBOX (best-effort local semantics).
        _add("INBOX")

    labels = _dedupe(labels)

    # Derived fields per constraints.
    is_read = ("UNREAD" not in labels)
    is_trashed = ("TRASH" in labels)
    is_archived = ("INBOX" not in labels) and ("TRASH" not in labels) and ("SPAM" not in labels)

    # Persist mutation (no success without effect).
    before = {
        "labels": target.get("labels"),
        "is_read": target.get("is_read"),
        "is_trashed": target.get("is_trashed"),
        "is_archived": target.get("is_archived"),
    }
    after = {"labels": labels, "is_read": is_read, "is_trashed": is_trashed, "is_archived": is_archived}

    if before == after:
        # It can be idempotent at message state level; still a real effect isn't required if already in desired state,
        # but we MUST return a succeeded tool_call and updated metadata (same).
        target["updated_at"] = _iso(_now())
    else:
        target["labels"] = labels
        target["is_read"] = bool(is_read)
        target["is_trashed"] = bool(is_trashed)
        target["is_archived"] = bool(is_archived)
        target["updated_at"] = _iso(_now())

    _save("gmail_messages.json", msg_rows)

    updated_message = dict(target)

    summary = {
        "message": "Email modified",
        "action": action,
        "updated_message": {
            "id": updated_message.get("id"),
            "gmail_message_id": updated_message.get("gmail_message_id"),
            "gmail_thread_id": updated_message.get("gmail_thread_id"),
            "subject": updated_message.get("subject"),
            "from": updated_message.get("from"),
            "to": updated_message.get("to"),
            "cc": updated_message.get("cc"),
            "snippet": updated_message.get("snippet"),
            "internal_date": updated_message.get("internal_date"),
            "labels": updated_message.get("labels"),
            "is_read": updated_message.get("is_read"),
            "is_trashed": updated_message.get("is_trashed"),
            "is_archived": updated_message.get("is_archived"),
            "status": updated_message.get("status"),
            "updated_at": updated_message.get("updated_at"),
        },
    }

    _update_tool_call(
        tool_calls_rows,
        call_id,
        status="succeeded",
        http_status=200,
        finished_at=_iso(_now()),
        result_summary=summary,
        touched_gmail_message_ids=[updated_message.get("id")],
    )

    return {
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_call_id": call_id,
        "idempotency_key": idempotency_key,
        "updated_message": updated_message,
    }

def list_events(workspace_id, identity_id, calendar_id=None, time_min=None, time_max=None, limit=None, cursor=None, sort=None, include_cancelled=None, **_extra):
    import json, os, datetime, time, base64, hashlib, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id or ""):
        return _err("VALIDATION_ERROR", "Invalid identity_id.")
    if calendar_id is not None and not isinstance(calendar_id, str):
        return _err("VALIDATION_ERROR", "calendar_id must be a string.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "start_time_asc"
    if sort not in ("start_time_asc", "start_time_desc"):
        return _err("VALIDATION_ERROR", "sort must be one of: start_time_asc, start_time_desc.")
    if include_cancelled is None:
        include_cancelled = False
    if not isinstance(include_cancelled, bool):
        return _err("VALIDATION_ERROR", "include_cancelled must be a boolean.")
    if time_min is not None and not isinstance(time_min, str):
        return _err("VALIDATION_ERROR", "time_min must be an RFC3339 date-time string.")
    if time_max is not None and not isinstance(time_max, str):
        return _err("VALIDATION_ERROR", "time_max must be an RFC3339 date-time string.")

    def _parse_dt(s):
        if s is None:
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    dt_min = _parse_dt(time_min)
    dt_max = _parse_dt(time_max)
    if time_min is not None and dt_min is None:
        return _err("VALIDATION_ERROR", "time_min is not a valid RFC3339 date-time.")
    if time_max is not None and dt_max is None:
        return _err("VALIDATION_ERROR", "time_max is not a valid RFC3339 date-time.")
    if dt_min is not None and dt_max is not None and dt_max <= dt_min:
        return _err("VALIDATION_ERROR", "time_max must be later than time_min.")

    # Load stores
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    events = _load("calendar_events.json")
    tool_calls = _load("tool_calls.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

    ident = next((i for i in identities if i.get("id") == identity_id and i.get("workspace_id") == workspace_id), None)
    if not ident:
        return _err("NOT_FOUND", "Google identity not found for workspace.")

    # Prepare to record tool call (must be recorded every call)
    def _new_id(prefix):
        # deterministic-ish but unique enough for local store
        raw = f"{prefix}_{now_iso}_{secrets.token_hex(8)}"
        h = hashlib.sha1(raw.encode("utf-8")).hexdigest().upper()
        return f"{prefix}_{h[:12]}"

    tool_call_id = _new_id("gws_tc")
    tc = {
        "id": tool_call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": "list_events",
        "request_params": {
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            **({"calendar_id": calendar_id} if calendar_id is not None else {}),
            **({"time_min": time_min} if time_min is not None else {}),
            **({"time_max": time_max} if time_max is not None else {}),
            "limit": limit,
            **({"cursor": cursor} if cursor is not None else {}),
            "sort": sort,
            "include_cancelled": include_cancelled,
        },
        "idempotency_key": None,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Enforce quota prior to "contacting Google" (we don't contact Google here, but still enforce at entry)
    # Quota counts tool_calls with status in ('succeeded','failed') per UTC day.
    def _utc_day_prefix(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    today = _utc_day_prefix(now)
    quota = ws.get("daily_tool_call_quota", 0)
    if not isinstance(quota, int) or quota < 0:
        quota = 0
    used = 0
    for r in tool_calls:
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("status") not in ("succeeded", "failed"):
            continue
        ca = r.get("created_at")
        if isinstance(ca, str):
            d = _parse_dt(ca)
            if d and _utc_day_prefix(d) == today:
                used += 1
    if quota == 0:
        # Interpret 0 as "no calls allowed" (strict)
        tc["status"] = "failed"
        tc["error_code"] = "quota_exceeded"
        tc["error_message"] = "Workspace daily tool call quota exceeded."
        tc["http_status"] = 429
        tc["started_at"] = now_iso
        tc["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        tc["updated_at"] = tc["finished_at"]
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return _err("QUOTA_EXCEEDED", "Workspace daily tool call quota exceeded.", quota=quota, used=used)
    if used >= quota:
        tc["status"] = "failed"
        tc["error_code"] = "quota_exceeded"
        tc["error_message"] = "Workspace daily tool call quota exceeded."
        tc["http_status"] = 429
        tc["started_at"] = now_iso
        tc["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        tc["updated_at"] = tc["finished_at"]
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return _err("QUOTA_EXCEEDED", "Workspace daily tool call quota exceeded.", quota=quota, used=used)

    # Identity must be active for Google-backed tools
    if ident.get("status") != "active":
        code = "needs_reauth" if ident.get("status") == "needs_reauth" else "revoked" if ident.get("status") == "revoked" else "deleted"
        tc["status"] = "failed"
        tc["error_code"] = code
        tc["error_message"] = "Google identity is not active."
        tc["http_status"] = 401
        tc["started_at"] = now_iso
        tc["finished_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        tc["updated_at"] = tc["finished_at"]
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "Google identity is not active.", identity_status=ident.get("status"))

    # Mark running
    tc["status"] = "running"
    tc["started_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    tc["updated_at"] = tc["started_at"]
    tool_calls.append(tc)
    _save("tool_calls.json", tool_calls)

    # Cache staleness check: if no events for scope or last_synced_at too old, "refresh"
    retention_days = ws.get("retention_days", 30)
    if not isinstance(retention_days, int) or retention_days < 1:
        retention_days = 30
    stale_before = now - datetime.timedelta(days=retention_days)

    cal = calendar_id if calendar_id else "primary"

    scoped = [e for e in events if e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id and e.get("google_calendar_id") == cal]
    any_fresh = any((_parse_dt(e.get("last_synced_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)) >= stale_before for e in scoped) if scoped else False

    refreshed = False
    if not scoped or not any_fresh:
        # Simulate a refresh: mark last_synced_at for scoped events and update identity calendar_sync_token
        refreshed = True
        ts = datetime.datetime.now(datetime.timezone.utc).isoformat()
        touched_ids = []
        for e in scoped:
            e["last_synced_at"] = ts
            e["updated_at"] = ts
            touched_ids.append(e.get("id"))
        ident["calendar_sync_token"] = "sync_" + hashlib.sha1(f"{identity_id}:{cal}:{ts}".encode("utf-8")).hexdigest()[:16]
        ident["updated_at"] = ts
        _save("calendar_events.json", events)
        _save("google_identities.json", identities)
    else:
        touched_ids = []

    # Filter by window
    def _event_start(e):
        return _parse_dt(e.get("start_time"))

    filtered = []
    for e in scoped:
        if e.get("status") == "deleted" or e.get("status") == "tombstoned":
            continue
        if (not include_cancelled) and e.get("status") == "cancelled":
            continue
        st = _event_start(e)
        if st is None:
            continue
        if dt_min is not None and st < dt_min:
            continue
        if dt_max is not None and st >= dt_max:
            continue
        filtered.append(e)

    reverse = (sort == "start_time_desc")
    filtered.sort(key=lambda x: (_event_start(x) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), x.get("id", "")), reverse=reverse)

    # Pagination cursor as base64url of offset integer
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            decoded = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            if decoded.startswith("o:"):
                offset = int(decoded.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Finish tool call
    finished = datetime.datetime.now(datetime.timezone.utc).isoformat()
    # Update the last appended tool_call row in-place
    for r in reversed(tool_calls):
        if r.get("id") == tool_call_id:
            r["status"] = "succeeded"
            r["http_status"] = 200
            r["result_summary"] = {"returned": len(page), "total": len(filtered), "refreshed": refreshed}
            r["touched_calendar_event_ids"] = list({*(touched_ids or []), *[x.get("id") for x in page if x.get("id")]}) or None
            r["finished_at"] = finished
            r["updated_at"] = finished
            break
    _save("tool_calls.json", tool_calls)

    return {
        "events": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "calendar_id": cal,
            "refreshed": refreshed,
        },
    }

def create_event(workspace_id, identity_id, calendar_id=None, title=None, description=None, location=None, start_time=None, end_time=None, timezone=None, attendees=None, conference_data=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, hashlib, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id or ""):
        return _err("VALIDATION_ERROR", "Invalid identity_id.")
    if calendar_id is not None and not isinstance(calendar_id, str):
        return _err("VALIDATION_ERROR", "calendar_id must be a string.")
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "title is required.")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string.")
    if location is not None and not isinstance(location, str):
        return _err("VALIDATION_ERROR", "location must be a string.")
    if not isinstance(start_time, str):
        return _err("VALIDATION_ERROR", "start_time is required and must be an RFC3339 date-time string.")
    if not isinstance(end_time, str):
        return _err("VALIDATION_ERROR", "end_time is required and must be an RFC3339 date-time string.")
    if timezone is not None and not isinstance(timezone, str):
        return _err("VALIDATION_ERROR", "timezone must be a string.")
    if attendees is not None:
        if not isinstance(attendees, list) or any((not isinstance(a, str) or not a.strip()) for a in attendees):
            return _err("VALIDATION_ERROR", "attendees must be an array of non-empty strings.")
    if conference_data is not None and not isinstance(conference_data, dict):
        return _err("VALIDATION_ERROR", "conference_data must be an object.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "idempotency_key must be a string.")

    def _parse_dt(s):
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    st = _parse_dt(start_time)
    en = _parse_dt(end_time)
    if st is None:
        return _err("VALIDATION_ERROR", "start_time is not a valid RFC3339 date-time.")
    if en is None:
        return _err("VALIDATION_ERROR", "end_time is not a valid RFC3339 date-time.")
    if en <= st:
        return _err("VALIDATION_ERROR", "end_time must be after start_time.")

    # Load stores
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    events = _load("calendar_events.json")
    tool_calls = _load("tool_calls.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

    ident = next((i for i in identities if i.get("id") == identity_id and i.get("workspace_id") == workspace_id), None)
    if not ident:
        return _err("NOT_FOUND", "Google identity not found for workspace.")

    cal = calendar_id if calendar_id else "primary"

    def _new_id(prefix):
        raw = f"{prefix}_{now_iso}_{secrets.token_hex(8)}"
        h = hashlib.sha1(raw.encode("utf-8")).hexdigest().upper()
        return f"{prefix}_{h[:12]}"

    # Idempotency: return original result if tool_call exists
    if idempotency_key:
        existing = next((r for r in tool_calls
                         if r.get("workspace_id") == workspace_id and r.get("tool_name") == "create_event"
                         and r.get("idempotency_key") == idempotency_key), None)
        if existing:
            # Record a new tool_call for this execution attempt (reads should also log; retries should log too)
            tool_call_id = _new_id("gws_tc")
            tc_retry = {
                "id": tool_call_id,
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                "tool_name": "create_event",
                "request_params": {
                    "workspace_id": workspace_id,
                    "identity_id": identity_id,
                    **({"calendar_id": calendar_id} if calendar_id is not None else {}),
                    "title": title,
                    **({"description": description} if description is not None else {}),
                    **({"location": location} if location is not None else {}),
                    "start_time": start_time,
                    "end_time": end_time,
                    **({"timezone": timezone} if timezone is not None else {}),
                    **({"attendees": attendees} if attendees is not None else {}),
                    **({"conference_data": conference_data} if conference_data is not None else {}),
                    "idempotency_key": idempotency_key,
                },
                "idempotency_key": idempotency_key,
                "status": "succeeded" if existing.get("status") == "succeeded" else "failed",
                "http_status": existing.get("http_status"),
                "error_code": existing.get("error_code"),
                "error_message": existing.get("error_message"),
                "result_summary": existing.get("result_summary"),
                "touched_gmail_message_ids": None,
                "touched_calendar_event_ids": existing.get("touched_calendar_event_ids"),
                "started_at": now_iso,
                "finished_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                "created_at": now_iso,
                "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            }
            tool_calls.append(tc_retry)
            _save("tool_calls.json", tool_calls)

            # If original succeeded and has touched event id, return that row
            touched = (existing.get("touched_calendar_event_ids") or [])
            if existing.get("status") == "succeeded" and touched:
                evt = next((e for e in events if e.get("id") == touched[0] and e.get("workspace_id") == workspace_id), None)
                if evt:
                    return {"event": evt, "meta": {"idempotent_replay": True}}
            return _err("CONFLICT", "Idempotency key already used for a prior create_event, but original result is unavailable.")

    # Enforce quota
    def _utc_day_prefix(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()
    def _parse_any_dt(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    today = _utc_day_prefix(now)
    quota = ws.get("daily_tool_call_quota", 0)
    if not isinstance(quota, int) or quota < 0:
        quota = 0
    used = 0
    for r in tool_calls:
        if r.get("workspace_id") != workspace_id:
            continue
        if r.get("status") not in ("succeeded", "failed"):
            continue
        d = _parse_any_dt(r.get("created_at"))
        if d and _utc_day_prefix(d) == today:
            used += 1
    if quota == 0 or used >= quota:
        # Still must persist audit record
        tool_call_id = _new_id("gws_tc")
        tc = {
            "id": tool_call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": "create_event",
            "request_params": {
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                **({"calendar_id": calendar_id} if calendar_id is not None else {}),
                "title": title,
                **({"description": description} if description is not None else {}),
                **({"location": location} if location is not None else {}),
                "start_time": start_time,
                "end_time": end_time,
                **({"timezone": timezone} if timezone is not None else {}),
                **({"attendees": attendees} if attendees is not None else {}),
                **({"conference_data": conference_data} if conference_data is not None else {}),
                **({"idempotency_key": idempotency_key} if idempotency_key is not None else {}),
            },
            "idempotency_key": idempotency_key,
            "status": "failed",
            "http_status": 429,
            "error_code": "quota_exceeded",
            "error_message": "Workspace daily tool call quota exceeded.",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": now_iso,
            "finished_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "created_at": now_iso,
            "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return _err("QUOTA_EXCEEDED", "Workspace daily tool call quota exceeded.", quota=quota, used=used)

    # Identity must be active
    if ident.get("status") != "active":
        code = "needs_reauth" if ident.get("status") == "needs_reauth" else "revoked" if ident.get("status") == "revoked" else "deleted"
        tool_call_id = _new_id("gws_tc")
        tc = {
            "id": tool_call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": "create_event",
            "request_params": {
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                **({"calendar_id": calendar_id} if calendar_id is not None else {}),
                "title": title,
                "start_time": start_time,
                "end_time": end_time,
            },
            "idempotency_key": idempotency_key,
            "status": "failed",
            "http_status": 401,
            "error_code": code,
            "error_message": "Google identity is not active.",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": now_iso,
            "finished_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "created_at": now_iso,
            "updated_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "Google identity is not active.", identity_status=ident.get("status"))

    # Create tool_call row (received -> running)
    tool_call_id = _new_id("gws_tc")
    tc = {
        "id": tool_call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": "create_event",
        "request_params": {
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            **({"calendar_id": calendar_id} if calendar_id is not None else {}),
            "title": title,
            **({"description": description} if description is not None else {}),
            **({"location": location} if location is not None else {}),
            "start_time": start_time,
            "end_time": end_time,
            **({"timezone": timezone} if timezone is not None else {}),
            **({"attendees": attendees} if attendees is not None else {}),
            **({"conference_data": conference_data} if conference_data is not None else {}),
            **({"idempotency_key": idempotency_key} if idempotency_key is not None else {}),
        },
        "idempotency_key": idempotency_key,
        "status": "received",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_calls.append(tc)
    _save("tool_calls.json", tool_calls)

    # Insert local pending_create row
    evt_id = _new_id("gws_evt")
    evt = {
        "id": evt_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "google_calendar_id": cal,
        "google_event_id": None,
        "ical_uid": None,
        "title": title,
        "description": description,
        "location": location,
        "start_time": st.isoformat(),
        "end_time": en.isoformat(),
        "timezone": timezone,
        "attendees": ([{"email": a, "responseStatus": "needsAction"} for a in attendees] if attendees is not None else None),
        "conference_data": conference_data,
        "etag": None,
        "status": "scheduled",
        "write_state": "pending_create",
        "last_error": None,
        "last_synced_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    events.append(evt)
    _save("calendar_events.json", events)

    # Attempt "Google create" (offline simulation): always succeed unless workspace/identity not active (already checked)
    # On success: set google_event_id, etag, write_state='synced', last_synced_at
    finished = datetime.datetime.now(datetime.timezone.utc).isoformat()
    google_event_id_val = "evt_" + hashlib.sha1(f"{workspace_id}:{identity_id}:{evt_id}:{finished}".encode("utf-8")).hexdigest()[:20]
    etag_val = "etag_" + hashlib.sha1(f"{google_event_id_val}:{finished}".encode("utf-8")).hexdigest()[:16]
    evt["google_event_id"] = google_event_id_val
    evt["etag"] = etag_val
    evt["write_state"] = "synced"
    evt["last_synced_at"] = finished
    evt["updated_at"] = finished
    _save("calendar_events.json", events)

    # Update tool_call to succeeded
    for r in reversed(tool_calls):
        if r.get("id") == tool_call_id:
            r["status"] = "succeeded"
            r["http_status"] = 200
            r["started_at"] = r.get("started_at") or now_iso
            r["finished_at"] = finished
            r["updated_at"] = finished
            r["result_summary"] = {"event_id": evt_id, "google_event_id": google_event_id_val}
            r["touched_calendar_event_ids"] = [evt_id]
            break
    _save("tool_calls.json", tool_calls)

    return {"event": evt}

def update_event(workspace_id, identity_id, event_id=None, google_event_id=None, calendar_id=None, title=None, description=None, location=None, start_time=None, end_time=None, timezone=None, attendees=None, conference_data=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "update_event"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _new_id(prefix):
        n = _now()
        seed = f"{prefix}:{n.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:18].upper()}"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("invalid datetime")
        txt = s.strip()
        if txt.endswith("Z"):
            txt = txt[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(txt)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _count_day_used(tool_calls_rows, ws_id, day):
        used = 0
        for r in tool_calls_rows:
            if r.get("workspace_id") != ws_id:
                continue
            if r.get("status") not in ("succeeded", "failed"):
                continue
            t = r.get("created_at") or r.get("started_at") or r.get("updated_at")
            if isinstance(t, str) and len(t) >= 10 and t[:10] == day:
                used += 1
        return used

    def _append_tool_call(tool_calls_rows, row):
        tool_calls_rows.append(row)
        _save("tool_calls.json", tool_calls_rows)

    def _update_tool_call(tool_calls_rows, call_id, **updates):
        for r in tool_calls_rows:
            if r.get("id") == call_id:
                r.update(updates)
                r["updated_at"] = _iso(_now())
                _save("tool_calls.json", tool_calls_rows)
                return r
        _save("tool_calls.json", tool_calls_rows)
        return None

    # --- Validate inputs (do NOT reject if both identifiers provided; prefer event_id) ---
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must match ^gws_ws_[0-9A-Z]+$")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id or ""):
        return _err("VALIDATION_ERROR", "identity_id must match ^gws_gid_[0-9A-Z]+$")
    if (event_id is None or str(event_id).strip() == "") and (google_event_id is None or str(google_event_id).strip() == ""):
        return _err("VALIDATION_ERROR", "Provide event_id or google_event_id")
    if event_id is not None and not isinstance(event_id, str):
        return _err("VALIDATION_ERROR", "event_id must be a string")
    if google_event_id is not None and not isinstance(google_event_id, str):
        return _err("VALIDATION_ERROR", "google_event_id must be a string")
    if calendar_id is not None and not isinstance(calendar_id, str):
        return _err("VALIDATION_ERROR", "calendar_id must be a string")
    if timezone is not None and not isinstance(timezone, str):
        return _err("VALIDATION_ERROR", "timezone must be a string")
    if attendees is not None:
        if not isinstance(attendees, list) or any((not isinstance(a, str) or not a.strip()) for a in attendees):
            return _err("VALIDATION_ERROR", "attendees must be an array of non-empty strings")
    if conference_data is not None and not isinstance(conference_data, dict):
        return _err("VALIDATION_ERROR", "conference_data must be an object")

    # parse times if provided; enforce end > start only when both supplied
    try:
        st = _parse_rfc3339(start_time) if start_time is not None else None
        et = _parse_rfc3339(end_time) if end_time is not None else None
    except ValueError:
        return _err("VALIDATION_ERROR", "start_time/end_time must be RFC3339 date-time strings")
    if st is not None and et is not None and not (et > st):
        return _err("VALIDATION_ERROR", "end_time must be after start_time")

    # --- Load ---
    now = _now()
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    events = _load("calendar_events.json")
    tool_calls = _load("tool_calls.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_status=ws.get("status"))

    ident = next((g for g in identities if g.get("id") == identity_id and g.get("workspace_id") == workspace_id), None)
    if not ident or ident.get("status") == "deleted":
        return _err("NOT_FOUND", "Identity not found")
    if ident.get("status") != "active":
        call_id = _new_id("gws_call")
        tc = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": tool_name,
            "request_params": {
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                "event_id": event_id,
                "google_event_id": google_event_id,
                "calendar_id": calendar_id,
                "title": title,
                "description": description,
                "location": location,
                "start_time": start_time,
                "end_time": end_time,
                "timezone": timezone,
                "attendees": attendees,
                "conference_data": conference_data,
                "idempotency_key": idempotency_key,
            },
            "idempotency_key": idempotency_key,
            "status": "failed",
            "http_status": 401,
            "error_code": "needs_reauth" if ident.get("status") == "needs_reauth" else ("revoked" if ident.get("status") == "revoked" else "invalid_identity_state"),
            "error_message": f"Identity status is {ident.get('status')}",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_tool_call(tool_calls, tc)
        return _err("UNAUTHORIZED", "Identity not active", identity_status=ident.get("status"))

    # quota
    quota = ws.get("daily_tool_call_quota")
    if isinstance(quota, int) and quota >= 0:
        day = _utc_day(now)
        used = _count_day_used(tool_calls, workspace_id, day)
        if used >= quota:
            call_id = _new_id("gws_call")
            tc = {
                "id": call_id,
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                "tool_name": tool_name,
                "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "calendar_id": calendar_id},
                "idempotency_key": idempotency_key,
                "status": "failed",
                "http_status": 429,
                "error_code": "quota_exceeded",
                "error_message": "Daily tool call quota exceeded",
                "result_summary": {"quota": quota, "used": used},
                "touched_gmail_message_ids": None,
                "touched_calendar_event_ids": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            _append_tool_call(tool_calls, tc)
            return _err("QUOTA_EXCEEDED", "Daily tool call quota exceeded", quota=quota, used=used)

    # idempotency: return prior succeeded
    if isinstance(idempotency_key, str) and idempotency_key.strip():
        for r in tool_calls:
            if r.get("workspace_id") == workspace_id and r.get("tool_name") == tool_name and r.get("idempotency_key") == idempotency_key:
                if r.get("status") == "succeeded" and isinstance(r.get("result_summary"), dict) and r["result_summary"].get("event_id"):
                    ev_id = r["result_summary"]["event_id"]
                    ev = next((e for e in events if e.get("id") == ev_id and e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id), None)
                    if ev:
                        return {"event": ev, "tool_call": {"id": r.get("id"), "status": r.get("status"), "result_summary": r.get("result_summary")}}
                if r.get("status") == "failed":
                    return _err("CONFLICT", "Idempotent request previously failed", tool_call_id=r.get("id"), error_code=r.get("error_code"), error_message=r.get("error_message"))
                return _err("CONFLICT", "Idempotent request already in progress", tool_call_id=r.get("id"), status=r.get("status"))

    # create running tool_call
    call_id = _new_id("gws_call")
    tc = {
        "id": call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": tool_name,
        "request_params": {
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "event_id": event_id,
            "google_event_id": google_event_id,
            "calendar_id": calendar_id,
            "title": title,
            "description": description,
            "location": location,
            "start_time": start_time,
            "end_time": end_time,
            "timezone": timezone,
            "attendees": attendees,
            "conference_data": conference_data,
            "idempotency_key": idempotency_key,
        },
        "idempotency_key": idempotency_key,
        "status": "running",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _append_tool_call(tool_calls, tc)

    # resolve event (prefer event_id if given; otherwise by google_event_id + optional calendar_id)
    target = None
    if isinstance(event_id, str) and event_id.strip():
        target = next((e for e in events if e.get("id") == event_id and e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id), None)
    if target is None and isinstance(google_event_id, str) and google_event_id.strip():
        candidates = [e for e in events if e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id and e.get("google_event_id") == google_event_id]
        if calendar_id:
            candidates = [e for e in candidates if e.get("google_calendar_id") == calendar_id]
        if len(candidates) == 1:
            target = candidates[0]
        elif len(candidates) > 1:
            _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="ambiguous", error_message="Multiple events match google_event_id; specify calendar_id", finished_at=_iso(_now()))
            return _err("CONFLICT", "Multiple events match google_event_id; specify calendar_id")
        else:
            target = None

    if not target:
        _update_tool_call(tool_calls, call_id, status="failed", http_status=404, error_code="not_found", error_message="Event not found", finished_at=_iso(_now()), result_summary={"found": False})
        return _err("NOT_FOUND", "Event not found")

    # apply write_state transition synced -> pending_update required by business rules, and lifecycle transitions
    transitions = {
        "pending_create": {"synced", "error"},
        "pending_update": {"synced", "error"},
        "pending_delete": {"synced", "error"},
        "error": {"pending_create", "pending_update", "pending_delete", "synced"},
        "synced": {"pending_update", "pending_delete", "error"},
    }
    cur = target.get("write_state")
    if cur not in transitions:
        cur = "synced"
        target["write_state"] = cur
    if "pending_update" not in transitions.get(cur, set()):
        _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="invalid_transition", error_message=f"Cannot transition write_state from {cur} to pending_update", finished_at=_iso(_now()))
        return _err("INVALID_TRANSITION", f"Cannot transition write_state from {cur} to pending_update")

    # set pending_update before "calling Google"
    target["write_state"] = "pending_update"
    target["last_error"] = None
    target["updated_at"] = _iso(_now())
    _save("calendar_events.json", events)

    # offline "Google call": assume success; set synced (legal from pending_update)
    target["write_state"] = "synced"
    if title is not None:
        if not isinstance(title, str):
            _update_tool_call(tool_calls, call_id, status="failed", http_status=400, error_code="invalid_request", error_message="title must be a string", finished_at=_iso(_now()))
            return _err("VALIDATION_ERROR", "title must be a string")
        target["title"] = title
    if description is not None:
        if not isinstance(description, str):
            _update_tool_call(tool_calls, call_id, status="failed", http_status=400, error_code="invalid_request", error_message="description must be a string", finished_at=_iso(_now()))
            return _err("VALIDATION_ERROR", "description must be a string")
        target["description"] = description
    if location is not None:
        if not isinstance(location, str):
            _update_tool_call(tool_calls, call_id, status="failed", http_status=400, error_code="invalid_request", error_message="location must be a string", finished_at=_iso(_now()))
            return _err("VALIDATION_ERROR", "location must be a string")
        target["location"] = location
    if st is not None:
        target["start_time"] = _iso(st)
    if et is not None:
        target["end_time"] = _iso(et)
    if (st is not None and et is not None) and not (_parse_rfc3339(target["end_time"]) > _parse_rfc3339(target["start_time"])):
        _update_tool_call(tool_calls, call_id, status="failed", http_status=400, error_code="invalid_request", error_message="end_time must be after start_time", finished_at=_iso(_now()))
        return _err("VALIDATION_ERROR", "end_time must be after start_time")
    if timezone is not None:
        target["timezone"] = timezone
    if attendees is not None:
        # store as attendee objects per schema (email + responseStatus placeholders)
        target["attendees"] = [{"email": a, "responseStatus": "needsAction"} for a in attendees]
    if conference_data is not None:
        target["conference_data"] = conference_data

    target["updated_at"] = _iso(_now())
    _save("calendar_events.json", events)

    _update_tool_call(
        tool_calls, call_id,
        status="succeeded",
        http_status=200,
        finished_at=_iso(_now()),
        result_summary={"event_id": target.get("id"), "google_event_id": target.get("google_event_id"), "calendar_id": target.get("google_calendar_id")},
        touched_calendar_event_ids=[target.get("id")],
    )

    return {"event": target, "tool_call": {"id": call_id, "status": "succeeded"}}

def delete_event(workspace_id, identity_id, event_id=None, google_event_id=None, calendar_id=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    tool_name = "delete_event"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _new_id(prefix):
        n = _now()
        seed = f"{prefix}:{n.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:18].upper()}"

    def _count_day_used(tool_calls_rows, ws_id, day):
        used = 0
        for r in tool_calls_rows:
            if r.get("workspace_id") != ws_id:
                continue
            if r.get("status") not in ("succeeded", "failed"):
                continue
            t = r.get("created_at") or r.get("started_at") or r.get("updated_at")
            if isinstance(t, str) and len(t) >= 10 and t[:10] == day:
                used += 1
        return used

    def _append_tool_call(tool_calls_rows, row):
        tool_calls_rows.append(row)
        _save("tool_calls.json", tool_calls_rows)

    def _update_tool_call(tool_calls_rows, call_id, **updates):
        for r in tool_calls_rows:
            if r.get("id") == call_id:
                r.update(updates)
                r["updated_at"] = _iso(_now())
                _save("tool_calls.json", tool_calls_rows)
                return r
        _save("tool_calls.json", tool_calls_rows)
        return None

    # validate (allow both identifiers; require at least one)
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must match ^gws_ws_[0-9A-Z]+$")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id or ""):
        return _err("VALIDATION_ERROR", "identity_id must match ^gws_gid_[0-9A-Z]+$")
    if (event_id is None or str(event_id).strip() == "") and (google_event_id is None or str(google_event_id).strip() == ""):
        return _err("VALIDATION_ERROR", "Provide event_id or google_event_id")
    if event_id is not None and not isinstance(event_id, str):
        return _err("VALIDATION_ERROR", "event_id must be a string")
    if google_event_id is not None and not isinstance(google_event_id, str):
        return _err("VALIDATION_ERROR", "google_event_id must be a string")
    if calendar_id is not None and not isinstance(calendar_id, str):
        return _err("VALIDATION_ERROR", "calendar_id must be a string")

    now = _now()
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    events = _load("calendar_events.json")
    tool_calls = _load("tool_calls.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_status=ws.get("status"))

    ident = next((g for g in identities if g.get("id") == identity_id and g.get("workspace_id") == workspace_id), None)
    if not ident or ident.get("status") == "deleted":
        return _err("NOT_FOUND", "Identity not found")
    if ident.get("status") != "active":
        call_id = _new_id("gws_call")
        tc = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": tool_name,
            "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "calendar_id": calendar_id, "idempotency_key": idempotency_key},
            "idempotency_key": idempotency_key,
            "status": "failed",
            "http_status": 401,
            "error_code": "needs_reauth" if ident.get("status") == "needs_reauth" else ("revoked" if ident.get("status") == "revoked" else "invalid_identity_state"),
            "error_message": f"Identity status is {ident.get('status')}",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_tool_call(tool_calls, tc)
        return _err("UNAUTHORIZED", "Identity not active", identity_status=ident.get("status"))

    # quota
    quota = ws.get("daily_tool_call_quota")
    if isinstance(quota, int) and quota >= 0:
        day = _utc_day(now)
        used = _count_day_used(tool_calls, workspace_id, day)
        if used >= quota:
            call_id = _new_id("gws_call")
            tc = {
                "id": call_id,
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                "tool_name": tool_name,
                "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "calendar_id": calendar_id},
                "idempotency_key": idempotency_key,
                "status": "failed",
                "http_status": 429,
                "error_code": "quota_exceeded",
                "error_message": "Daily tool call quota exceeded",
                "result_summary": {"quota": quota, "used": used},
                "touched_gmail_message_ids": None,
                "touched_calendar_event_ids": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            _append_tool_call(tool_calls, tc)
            return _err("QUOTA_EXCEEDED", "Daily tool call quota exceeded", quota=quota, used=used)

    # idempotency
    if isinstance(idempotency_key, str) and idempotency_key.strip():
        for r in tool_calls:
            if r.get("workspace_id") == workspace_id and r.get("tool_name") == tool_name and r.get("idempotency_key") == idempotency_key:
                if r.get("status") == "succeeded" and isinstance(r.get("result_summary"), dict) and r["result_summary"].get("event_id"):
                    ev_id = r["result_summary"]["event_id"]
                    ev = next((e for e in events if e.get("id") == ev_id and e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id), None)
                    if ev:
                        return {"event": ev, "tool_call": {"id": r.get("id"), "status": r.get("status"), "result_summary": r.get("result_summary")}}
                if r.get("status") == "failed":
                    return _err("CONFLICT", "Idempotent request previously failed", tool_call_id=r.get("id"), error_code=r.get("error_code"), error_message=r.get("error_message"))
                return _err("CONFLICT", "Idempotent request already in progress", tool_call_id=r.get("id"), status=r.get("status"))

    # running tool_call
    call_id = _new_id("gws_call")
    tc = {
        "id": call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": tool_name,
        "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "calendar_id": calendar_id, "idempotency_key": idempotency_key},
        "idempotency_key": idempotency_key,
        "status": "running",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _append_tool_call(tool_calls, tc)

    # resolve target
    target = None
    if isinstance(event_id, str) and event_id.strip():
        target = next((e for e in events if e.get("id") == event_id and e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id), None)
    if target is None and isinstance(google_event_id, str) and google_event_id.strip():
        candidates = [e for e in events if e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id and e.get("google_event_id") == google_event_id]
        if calendar_id:
            candidates = [e for e in candidates if e.get("google_calendar_id") == calendar_id]
        if len(candidates) == 1:
            target = candidates[0]
        elif len(candidates) > 1:
            _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="ambiguous", error_message="Multiple events match google_event_id; specify calendar_id", finished_at=_iso(_now()))
            return _err("CONFLICT", "Multiple events match google_event_id; specify calendar_id")
        else:
            target = None

    if not target:
        _update_tool_call(tool_calls, call_id, status="failed", http_status=404, error_code="not_found", error_message="Event not found", finished_at=_iso(_now()), result_summary={"found": False})
        return _err("NOT_FOUND", "Event not found")

    # transition to pending_delete
    transitions = {
        "pending_create": {"synced", "error"},
        "pending_update": {"synced", "error"},
        "pending_delete": {"synced", "error"},
        "error": {"pending_create", "pending_update", "pending_delete", "synced"},
        "synced": {"pending_update", "pending_delete", "error"},
    }
    cur = target.get("write_state")
    if cur not in transitions:
        cur = "synced"
        target["write_state"] = cur
    if "pending_delete" not in transitions.get(cur, set()):
        _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="invalid_transition", error_message=f"Cannot transition write_state from {cur} to pending_delete", finished_at=_iso(_now()))
        return _err("INVALID_TRANSITION", f"Cannot transition write_state from {cur} to pending_delete")

    target["write_state"] = "pending_delete"
    target["last_error"] = None
    target["updated_at"] = _iso(_now())
    _save("calendar_events.json", events)

    # offline "Google delete": assume success; mark status deleted and synced
    target["status"] = "deleted"
    target["write_state"] = "synced"
    target["updated_at"] = _iso(_now())
    _save("calendar_events.json", events)

    _update_tool_call(
        tool_calls, call_id,
        status="succeeded",
        http_status=200,
        finished_at=_iso(_now()),
        result_summary={"event_id": target.get("id"), "google_event_id": target.get("google_event_id"), "calendar_id": target.get("google_calendar_id"), "deleted": True},
        touched_calendar_event_ids=[target.get("id")],
    )

    return {"event": target, "tool_call": {"id": call_id, "status": "succeeded"}}

def get_me(workspace_id=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_tool_call_id():
        return "gws_tc_" + uuid.uuid4().hex[:16].upper()

    def _log_call(ws_id, identity_id, status, http_status=None, error_code=None, error_message=None, result_summary=None):
        tool_calls = _load("tool_calls.json")
        row = {
            "id": _new_tool_call_id(),
            "workspace_id": ws_id,
            "identity_id": identity_id,
            "tool_name": "get_me",
            "request_params": {"workspace_id": workspace_id} if workspace_id is not None else {},
            "idempotency_key": None,
            "status": status,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_summary": result_summary,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # Validation
    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id):
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    tool_calls = _load("tool_calls.json")

    # Ambient auth resolution: find any usable workspace+identity combination.
    # For get_me, identity is optional, but we return one if present.
    ws = None
    if workspace_id:
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if ws is None:
            # treat as unauthorized to access/missing in this surface
            # (vendor says UNAUTHORIZED when credential invalid; we have no credential param, so choose NOT_FOUND?).
            # But tool specifies UNAUTHORIZED when missing/invalid credential; in ambient auth case, missing workspace => UNAUTHORIZED.
            return _err("UNAUTHORIZED", "Not authorized for the requested workspace.")
        if ws.get("status") != "active":
            # still allow get_me to report; but choose only active workspace if possible
            pass
    else:
        # default/primary workspace: first active, else any
        ws = next((w for w in workspaces if w.get("status") == "active"), None) or (workspaces[0] if workspaces else None)

    if ws is None:
        return _err("UNAUTHORIZED", "No accessible workspace for current credential.")

    # choose a representative identity in workspace (active preferred)
    ws_id = ws.get("id")
    ws_identities = [i for i in identities if i.get("workspace_id") == ws_id and i.get("status") != "deleted"]
    me_identity = None
    me_identity = next((i for i in ws_identities if i.get("status") == "active"), None) or (ws_identities[0] if ws_identities else None)

    # Quota consumption: succeeded/failed calls today UTC for this workspace
    start_day = now.replace(hour=0, minute=0, second=0, microsecond=0)
    consumed = 0
    for c in tool_calls:
        if c.get("workspace_id") != ws_id:
            continue
        if c.get("status") not in ("succeeded", "failed"):
            continue
        fin = _parse_dt(c.get("finished_at")) or _parse_dt(c.get("updated_at")) or _parse_dt(c.get("created_at"))
        if fin is None:
            continue
        if fin >= start_day and fin <= now + datetime.timedelta(days=1):
            consumed += 1

    quota = ws.get("daily_tool_call_quota")
    remaining = None
    if isinstance(quota, int) and quota >= 0:
        remaining = max(0, quota - consumed)

    result = {
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "default_timezone": ws.get("default_timezone"),
            "retention_days": ws.get("retention_days"),
            "daily_tool_call_quota": ws.get("daily_tool_call_quota"),
        },
        "identity": None,
        "entitlements": {
            "scopes": me_identity.get("scopes") if me_identity else [],
        },
        "quota": {
            "utc_day_start": _iso(start_day),
            "used": consumed,
            "limit": quota,
            "remaining": remaining,
        },
    }

    if me_identity:
        result["identity"] = {
            "id": me_identity.get("id"),
            "workspace_id": me_identity.get("workspace_id"),
            "google_user_id": me_identity.get("google_user_id"),
            "primary_email": me_identity.get("primary_email"),
            "display_name": me_identity.get("display_name"),
            "status": me_identity.get("status"),
            "scopes": me_identity.get("scopes"),
            "last_auth_at": me_identity.get("last_auth_at"),
            "created_at": me_identity.get("created_at"),
            "updated_at": me_identity.get("updated_at"),
        }

    _log_call(ws_id, me_identity.get("id") if me_identity else None, "succeeded", http_status=200,
              result_summary={"workspace_id": ws_id, "identity_id": me_identity.get("id") if me_identity else None,
                              "quota_used": consumed, "quota_limit": quota})
    return {"me": result, "latency_ms": int((time.time() - t0) * 1000)}

def list_google_identities(workspace_id, status=None, primary_email=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_tool_call_id():
        return "gws_tc_" + uuid.uuid4().hex[:16].upper()

    def _log_call(ws_id, status_s, http_status=None, error_code=None, error_message=None, result_summary=None):
        tool_calls = _load("tool_calls.json")
        row = {
            "id": _new_tool_call_id(),
            "workspace_id": ws_id,
            "identity_id": None,
            "tool_name": "list_google_identities",
            "request_params": {
                "workspace_id": workspace_id,
                **({} if status is None else {"status": status}),
                **({} if primary_email is None else {"primary_email": primary_email}),
                **({} if limit is None else {"limit": limit}),
                **({} if cursor is None else {"cursor": cursor}),
                **({} if sort is None else {"sort": sort}),
            },
            "idempotency_key": None,
            "status": status_s,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_summary": result_summary,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # Validation
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "needs_reauth", "revoked", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status.")
    if primary_email is not None and not isinstance(primary_email, str):
        return _err("VALIDATION_ERROR", "Invalid primary_email.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.")
    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in ("created_at_desc", "created_at_asc", "primary_email_asc"):
        return _err("VALIDATION_ERROR", "Invalid sort.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log_call(workspace_id, "failed", http_status=401, error_code="unauthorized", error_message="Workspace not accessible.")
        return _err("UNAUTHORIZED", "Not authorized for the requested workspace.")

    identities = [i for i in _load("google_identities.json") if i.get("workspace_id") == workspace_id]
    if status is not None:
        identities = [i for i in identities if i.get("status") == status]
    if primary_email is not None:
        pe = primary_email.strip().lower()
        identities = [i for i in identities if isinstance(i.get("primary_email"), str) and i.get("primary_email").lower() == pe]

    def _sort_key(i):
        if sort.startswith("created_at_"):
            dt = _parse_dt(i.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt
        if sort == "primary_email_asc":
            return (i.get("primary_email") or "").lower()
        return 0

    reverse = (sort == "created_at_desc")
    identities.sort(key=_sort_key, reverse=reverse)

    # cursor is an offset encoded
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("off:"):
                offset = int(raw.split(":", 1)[1])
            else:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(identities)
    page = identities[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        nxt = f"off:{offset + limit}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(nxt).decode("utf-8").rstrip("=")

    out_rows = []
    for i in page:
        out_rows.append({
            "id": i.get("id"),
            "workspace_id": i.get("workspace_id"),
            "google_user_id": i.get("google_user_id"),
            "primary_email": i.get("primary_email"),
            "display_name": i.get("display_name"),
            "scopes": i.get("scopes"),
            "status": i.get("status"),
            "last_auth_at": i.get("last_auth_at"),
            "created_at": i.get("created_at"),
            "updated_at": i.get("updated_at"),
        })

    _log_call(workspace_id, "succeeded", http_status=200,
              result_summary={"returned": len(out_rows), "total": total, "next_cursor": bool(next_cursor)})
    return {
        "data": out_rows,
        "pagination": {"total": total, "has_more": bool(next_cursor), "next_cursor": next_cursor, "limit": limit},
        "latency_ms": int((time.time() - t0) * 1000),
    }

def create_google_identity(workspace_id, auth_flow, authorization_code=None, redirect_uri=None, refresh_token=None, access_token=None, token_expiry=None, scopes=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_tool_call_id():
        return "gws_tc_" + uuid.uuid4().hex[:16].upper()

    def _new_identity_id():
        return "gws_gid_" + uuid.uuid4().hex[:16].upper()

    def _log_call(ws_id, identity_id, status_s, http_status=None, error_code=None, error_message=None, result_summary=None):
        tool_calls = _load("tool_calls.json")
        row = {
            "id": _new_tool_call_id(),
            "workspace_id": ws_id,
            "identity_id": identity_id,
            "tool_name": "create_google_identity",
            "request_params": {
                "workspace_id": workspace_id,
                "auth_flow": auth_flow,
                **({} if authorization_code is None else {"authorization_code": "***"}),
                **({} if redirect_uri is None else {"redirect_uri": redirect_uri}),
                **({} if refresh_token is None else {"refresh_token": "***"}),
                **({} if access_token is None else {"access_token": "***"}),
                **({} if token_expiry is None else {"token_expiry": token_expiry}),
                "scopes": scopes,
                **({} if idempotency_key is None else {"idempotency_key": idempotency_key}),
            },
            "idempotency_key": idempotency_key,
            "status": status_s,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_summary": result_summary,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # Validation
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(auth_flow, str) or auth_flow not in ("authorization_code", "refresh_token"):
        return _err("VALIDATION_ERROR", "Invalid auth_flow.")
    if scopes is None or not isinstance(scopes, list) or len(scopes) < 1 or any(not isinstance(s, str) or not s for s in scopes):
        return _err("VALIDATION_ERROR", "Invalid scopes; must be a non-empty array of strings.")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        return _err("VALIDATION_ERROR", "Invalid idempotency_key.")

    if auth_flow == "authorization_code":
        if not isinstance(authorization_code, str) or not authorization_code.strip():
            return _err("VALIDATION_ERROR", "authorization_code is required when auth_flow=authorization_code.")
        if not isinstance(redirect_uri, str) or not redirect_uri.strip():
            return _err("VALIDATION_ERROR", "redirect_uri is required when auth_flow=authorization_code.")
    else:
        if not isinstance(refresh_token, str) or not refresh_token.strip():
            return _err("VALIDATION_ERROR", "refresh_token is required when auth_flow=refresh_token.")
        if access_token is not None and (not isinstance(access_token, str) or not access_token.strip()):
            return _err("VALIDATION_ERROR", "Invalid access_token.")
        if token_expiry is not None:
            if not isinstance(token_expiry, str) or _parse_dt(token_expiry) is None:
                return _err("VALIDATION_ERROR", "Invalid token_expiry; must be RFC3339 date-time string.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") != "active":
        _log_call(workspace_id, None, "failed", http_status=401, error_code="unauthorized", error_message="Workspace not accessible.")
        return _err("UNAUTHORIZED", "Not authorized for the requested workspace.")

    # Quota enforcement (UTC day, succeeded/failed)
    tool_calls = _load("tool_calls.json")
    start_day = now.replace(hour=0, minute=0, second=0, microsecond=0)
    used = 0
    for c in tool_calls:
        if c.get("workspace_id") != workspace_id:
            continue
        if c.get("status") not in ("succeeded", "failed"):
            continue
        fin = _parse_dt(c.get("finished_at")) or _parse_dt(c.get("updated_at")) or _parse_dt(c.get("created_at"))
        if fin and fin >= start_day and fin <= now + datetime.timedelta(days=1):
            used += 1
    quota = ws.get("daily_tool_call_quota")
    if isinstance(quota, int) and quota >= 0 and used >= quota:
        _log_call(workspace_id, None, "failed", http_status=429, error_code="quota_exceeded", error_message="Daily tool call quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily tool call quota exceeded.", limit=quota, used=used)

    # Idempotency for identity linking: use tool_calls unique(workspace_id, tool_name, idempotency_key)
    if idempotency_key:
        prev = None
        for c in tool_calls:
            if c.get("workspace_id") == workspace_id and c.get("tool_name") == "create_google_identity" and c.get("idempotency_key") == idempotency_key:
                if c.get("status") == "succeeded":
                    prev = c
                    break
        if prev and isinstance(prev.get("result_summary"), dict):
            identity_id = prev["result_summary"].get("identity_id")
            if identity_id:
                identities = _load("google_identities.json")
                row = next((i for i in identities if i.get("id") == identity_id and i.get("workspace_id") == workspace_id), None)
                if row:
                    _log_call(workspace_id, row.get("id"), "succeeded", http_status=200,
                              result_summary={"identity_id": row.get("id"), "idempotent_replay": True})
                    return {"identity": row, "idempotent_replay": True, "latency_ms": int((time.time() - t0) * 1000)}

    # Simulate OAuth exchange/profile retrieval deterministically without external calls.
    if auth_flow == "authorization_code":
        seed = f"authcode:{authorization_code.strip()}:{redirect_uri.strip()}:{workspace_id}"
        derived_refresh = "rt_" + hashlib.sha256(seed.encode("utf-8")).hexdigest()[:40]
        derived_access = "at_" + hashlib.sha256((seed + ":access").encode("utf-8")).hexdigest()[:40]
        exp = now + datetime.timedelta(hours=1)
        oauth_refresh = derived_refresh
        oauth_access = derived_access
        oauth_expiry = exp
    else:
        oauth_refresh = refresh_token.strip()
        oauth_access = (access_token.strip() if isinstance(access_token, str) and access_token.strip() else "at_" + hashlib.sha256((oauth_refresh + ":access").encode("utf-8")).hexdigest()[:40])
        parsed = _parse_dt(token_expiry) if token_expiry is not None else None
        oauth_expiry = parsed if parsed else (now + datetime.timedelta(hours=1))

    if oauth_expiry <= now:
        return _err("VALIDATION_ERROR", "oauth token_expiry must be in the future.")

    # Derive google user id/email deterministically from refresh token; caller can override later via update.
    gsub = "gusr_" + hashlib.sha256((oauth_refresh + ":" + workspace_id).encode("utf-8")).hexdigest()[:24]
    email_local = hashlib.sha256(gsub.encode("utf-8")).hexdigest()[:10]
    primary = f"user-{email_local}@example.com"

    identities = _load("google_identities.json")
    # Uniqueness: (workspace_id, google_user_id) and (workspace_id, primary_email)
    if any(i for i in identities if i.get("workspace_id") == workspace_id and i.get("google_user_id") == gsub and i.get("status") != "deleted"):
        _log_call(workspace_id, None, "failed", http_status=409, error_code="conflict", error_message="Identity already linked (google_user_id).")
        return _err("CONFLICT", "Identity already linked to this workspace.")
    if any(i for i in identities if i.get("workspace_id") == workspace_id and isinstance(i.get("primary_email"), str) and i.get("primary_email").lower() == primary.lower() and i.get("status") != "deleted"):
        _log_call(workspace_id, None, "failed", http_status=409, error_code="conflict", error_message="Identity already linked (primary_email).")
        return _err("CONFLICT", "An identity with this primary_email already exists in this workspace.")

    identity_id = _new_identity_id()
    row = {
        "id": identity_id,
        "workspace_id": workspace_id,
        "google_user_id": gsub,
        "primary_email": primary,
        "display_name": None,
        "oauth_access_token": oauth_access,
        "oauth_refresh_token": oauth_refresh,
        "oauth_token_expiry": _iso(oauth_expiry),
        "scopes": list(scopes),
        "gmail_history_id": None,
        "calendar_sync_token": None,
        "status": "active",
        "last_auth_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    identities.append(row)
    _save("google_identities.json", identities)

    _log_call(workspace_id, identity_id, "succeeded", http_status=201, result_summary={"identity_id": identity_id})
    return {"identity": row, "latency_ms": int((time.time() - t0) * 1000)}

def update_google_identity(workspace_id, identity_id, status=None, display_name=None, primary_email=None, oauth_access_token=None, oauth_refresh_token=None, oauth_token_expiry=None, scopes=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_tool_call_id():
        return "gws_tc_" + uuid.uuid4().hex[:16].upper()

    def _log_call(ws_id, identity_id_log, status_s, http_status=None, error_code=None, error_message=None, result_summary=None):
        tool_calls = _load("tool_calls.json")
        row = {
            "id": _new_tool_call_id(),
            "workspace_id": ws_id,
            "identity_id": identity_id_log,
            "tool_name": "update_google_identity",
            "request_params": {
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                **({} if status is None else {"status": status}),
                **({} if display_name is None else {"display_name": display_name}),
                **({} if primary_email is None else {"primary_email": primary_email}),
                **({} if oauth_access_token is None else {"oauth_access_token": "***"}),
                **({} if oauth_refresh_token is None else {"oauth_refresh_token": "***"}),
                **({} if oauth_token_expiry is None else {"oauth_token_expiry": oauth_token_expiry}),
                **({} if scopes is None else {"scopes": scopes}),
            },
            "idempotency_key": None,
            "status": status_s,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "result_summary": result_summary,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # Validation
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id):
        return _err("VALIDATION_ERROR", "Invalid identity_id.")
    if status is not None and (not isinstance(status, str) or status not in ("active", "needs_reauth", "revoked", "deleted")):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "Invalid display_name.")
    if primary_email is not None and not isinstance(primary_email, str):
        return _err("VALIDATION_ERROR", "Invalid primary_email.")
    if oauth_access_token is not None and (not isinstance(oauth_access_token, str) or not oauth_access_token.strip()):
        return _err("VALIDATION_ERROR", "Invalid oauth_access_token.")
    if oauth_refresh_token is not None and (not isinstance(oauth_refresh_token, str) or not oauth_refresh_token.strip()):
        return _err("VALIDATION_ERROR", "Invalid oauth_refresh_token.")
    if oauth_token_expiry is not None:
        if not isinstance(oauth_token_expiry, str) or _parse_dt(oauth_token_expiry) is None:
            return _err("VALIDATION_ERROR", "Invalid oauth_token_expiry; must be RFC3339 date-time string.")
    if scopes is not None:
        if not isinstance(scopes, list) or any(not isinstance(s, str) or not s for s in scopes):
            return _err("VALIDATION_ERROR", "Invalid scopes; must be an array of strings.")
        if len(scopes) < 1:
            return _err("VALIDATION_ERROR", "scopes must have at least 1 item.")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None or ws.get("status") == "deleted":
        _log_call(workspace_id, identity_id, "failed", http_status=401, error_code="unauthorized", error_message="Workspace not accessible.")
        return _err("UNAUTHORIZED", "Not authorized for the requested workspace.")

    identities = _load("google_identities.json")
    idx = next((k for k, i in enumerate(identities) if i.get("id") == identity_id and i.get("workspace_id") == workspace_id), None)
    if idx is None:
        _log_call(workspace_id, identity_id, "failed", http_status=404, error_code="not_found", error_message="Identity not found.")
        return _err("NOT_FOUND", "Google identity not found in workspace.")
    row = identities[idx]

    # Lifecycle transitions
    transitions = {
        "active": {"needs_reauth", "revoked", "deleted"},
        "needs_reauth": {"active", "revoked", "deleted"},
        "revoked": {"deleted"},
        "deleted": set(),
    }
    if status is not None:
        cur = row.get("status")
        if cur not in transitions:
            return _err("VALIDATION_ERROR", "Identity has invalid current status.")
        if status != cur and status not in transitions[cur]:
            _log_call(workspace_id, identity_id, "failed", http_status=409, error_code="invalid_transition", error_message="Invalid status transition.")
            return _err("INVALID_TRANSITION", f"Cannot transition identity status from {cur} to {status}.")
        # Activating requires valid OAuth credentials (CONFLICT if missing/expired)
        if status == "active":
            new_access = oauth_access_token if oauth_access_token is not None else row.get("oauth_access_token")
            new_exp = _parse_dt(oauth_token_expiry) if oauth_token_expiry is not None else _parse_dt(row.get("oauth_token_expiry"))
            if not isinstance(new_access, str) or not new_access.strip() or new_exp is None or new_exp <= now:
                _log_call(workspace_id, identity_id, "failed", http_status=409, error_code="conflict", error_message="Cannot activate without valid OAuth credentials.")
                return _err("CONFLICT", "Cannot activate identity without a valid (non-expired) access token and expiry.")
        row["status"] = status

    # Uniqueness if primary_email change
    if primary_email is not None:
        pe = primary_email.strip()
        if not pe:
            return _err("VALIDATION_ERROR", "primary_email cannot be empty.")
        for i in identities:
            if i.get("id") == identity_id:
                continue
            if i.get("workspace_id") == workspace_id and isinstance(i.get("primary_email"), str) and i.get("primary_email").lower() == pe.lower() and i.get("status") != "deleted":
                _log_call(workspace_id, identity_id, "failed", http_status=409, error_code="conflict", error_message="primary_email already in use.")
                return _err("CONFLICT", "Another identity in this workspace already uses that primary_email.")
        row["primary_email"] = pe

    if display_name is not None:
        row["display_name"] = display_name

    if oauth_access_token is not None:
        row["oauth_access_token"] = oauth_access_token
        row["last_auth_at"] = _iso(now)
    if oauth_refresh_token is not None:
        row["oauth_refresh_token"] = oauth_refresh_token
        row["last_auth_at"] = _iso(now)
    if oauth_token_expiry is not None:
        dt = _parse_dt(oauth_token_expiry)
        if dt is None:
            return _err("VALIDATION_ERROR", "Invalid oauth_token_expiry.")
        row["oauth_token_expiry"] = _iso(dt)
    if scopes is not None:
        row["scopes"] = list(scopes)

    row["updated_at"] = _iso(now)

    identities[idx] = row
    _save("google_identities.json", identities)

    _log_call(workspace_id, identity_id, "succeeded", http_status=200, result_summary={"identity_id": identity_id})
    return {"identity": row, "latency_ms": int((time.time() - t0) * 1000)}

def get_calendar_event(workspace_id, identity_id, event_id=None, google_event_id=None, google_calendar_id=None, refresh=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0494000" if __import__("os").path.isdir("./environment_mix/0494000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # tool_calls enum doesn't include get_calendar_event; log as list_events
    log_tool_name = "list_events"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _utc_day(dt):
        return dt.astimezone(datetime.timezone.utc).date().isoformat()

    def _new_id(prefix):
        n = _now()
        seed = f"{prefix}:{n.timestamp()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")
        return f"{prefix}_{hashlib.sha256(seed).hexdigest()[:18].upper()}"

    def _count_day_used(tool_calls_rows, ws_id, day):
        used = 0
        for r in tool_calls_rows:
            if r.get("workspace_id") != ws_id:
                continue
            if r.get("status") not in ("succeeded", "failed"):
                continue
            t = r.get("created_at") or r.get("started_at") or r.get("updated_at")
            if isinstance(t, str) and len(t) >= 10 and t[:10] == day:
                used += 1
        return used

    def _append_tool_call(tool_calls_rows, row):
        tool_calls_rows.append(row)
        _save("tool_calls.json", tool_calls_rows)

    def _update_tool_call(tool_calls_rows, call_id, **updates):
        for r in tool_calls_rows:
            if r.get("id") == call_id:
                r.update(updates)
                r["updated_at"] = _iso(_now())
                _save("tool_calls.json", tool_calls_rows)
                return r
        _save("tool_calls.json", tool_calls_rows)
        return None

    # validate: accept either-or; DO NOT reject if both provided; require at least one
    if not isinstance(workspace_id, str) or not re.match(r"^gws_ws_[0-9A-Z]+$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "workspace_id must match ^gws_ws_[0-9A-Z]+$")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id or ""):
        return _err("VALIDATION_ERROR", "identity_id must match ^gws_gid_[0-9A-Z]+$")
    if (event_id is None or str(event_id).strip() == "") and (google_event_id is None or str(google_event_id).strip() == ""):
        return _err("VALIDATION_ERROR", "Provide event_id or google_event_id")
    if event_id is not None and not isinstance(event_id, str):
        return _err("VALIDATION_ERROR", "event_id must be a string")
    if google_event_id is not None and not isinstance(google_event_id, str):
        return _err("VALIDATION_ERROR", "google_event_id must be a string")
    if google_calendar_id is not None and not isinstance(google_calendar_id, str):
        return _err("VALIDATION_ERROR", "google_calendar_id must be a string")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean")

    now = _now()
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    events = _load("calendar_events.json")
    tool_calls = _load("tool_calls.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        # still log attempt
        call_id = _new_id("gws_call")
        tc = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": log_tool_name,
            "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "google_calendar_id": google_calendar_id, "refresh": refresh},
            "idempotency_key": None,
            "status": "failed",
            "http_status": 404,
            "error_code": "not_found",
            "error_message": "Workspace not found",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_tool_call(tool_calls, tc)
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        call_id = _new_id("gws_call")
        tc = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": log_tool_name,
            "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "google_calendar_id": google_calendar_id, "refresh": refresh},
            "idempotency_key": None,
            "status": "failed",
            "http_status": 403,
            "error_code": "forbidden",
            "error_message": f"Workspace status is {ws.get('status')}",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_tool_call(tool_calls, tc)
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_status=ws.get("status"))

    ident = next((g for g in identities if g.get("id") == identity_id and g.get("workspace_id") == workspace_id), None)
    if not ident or ident.get("status") == "deleted":
        call_id = _new_id("gws_call")
        tc = {
            "id": call_id,
            "workspace_id": workspace_id,
            "identity_id": identity_id,
            "tool_name": log_tool_name,
            "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "google_calendar_id": google_calendar_id, "refresh": refresh},
            "idempotency_key": None,
            "status": "failed",
            "http_status": 404,
            "error_code": "not_found",
            "error_message": "Identity not found",
            "result_summary": None,
            "touched_gmail_message_ids": None,
            "touched_calendar_event_ids": None,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_tool_call(tool_calls, tc)
        return _err("NOT_FOUND", "Identity not found")

    # quota check (read calls count as tool calls too once succeeded/failed)
    quota = ws.get("daily_tool_call_quota")
    if isinstance(quota, int) and quota >= 0:
        day = _utc_day(now)
        used = _count_day_used(tool_calls, workspace_id, day)
        if used >= quota:
            call_id = _new_id("gws_call")
            tc = {
                "id": call_id,
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                "tool_name": log_tool_name,
                "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "google_calendar_id": google_calendar_id, "refresh": refresh},
                "idempotency_key": None,
                "status": "failed",
                "http_status": 429,
                "error_code": "quota_exceeded",
                "error_message": "Daily tool call quota exceeded",
                "result_summary": {"quota": quota, "used": used},
                "touched_gmail_message_ids": None,
                "touched_calendar_event_ids": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            _append_tool_call(tool_calls, tc)
            return _err("QUOTA_EXCEEDED", "Daily tool call quota exceeded", quota=quota, used=used)

    # create running tool_call
    call_id = _new_id("gws_call")
    tc = {
        "id": call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": log_tool_name,
        "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "google_event_id": google_event_id, "google_calendar_id": google_calendar_id, "refresh": refresh},
        "idempotency_key": None,
        "status": "running",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _append_tool_call(tool_calls, tc)

    # resolve event (prefer internal id if provided)
    target = None
    if isinstance(event_id, str) and event_id.strip():
        target = next((e for e in events if e.get("id") == event_id and e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id), None)
    if target is None and isinstance(google_event_id, str) and google_event_id.strip():
        candidates = [e for e in events if e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id and e.get("google_event_id") == google_event_id]
        if google_calendar_id:
            candidates = [e for e in candidates if e.get("google_calendar_id") == google_calendar_id]
        if len(candidates) == 1:
            target = candidates[0]
        elif len(candidates) > 1:
            _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="ambiguous", error_message="Multiple events match google_event_id; specify google_calendar_id", finished_at=_iso(_now()))
            return _err("CONFLICT", "Multiple events match google_event_id; specify google_calendar_id")
        else:
            target = None

    if not target:
        _update_tool_call(tool_calls, call_id, status="failed", http_status=404, error_code="not_found", error_message="Event not found", finished_at=_iso(_now()), result_summary={"found": False})
        return _err("NOT_FOUND", "Event not found")

    # refresh behavior: offline store; only mark last_synced_at if requested and identity is active
    if refresh is True and ident.get("status") == "active":
        # simulate refresh by updating last_synced_at (no upstream)
        target["last_synced_at"] = _iso(_now())
        target["updated_at"] = _iso(_now())
        _save("calendar_events.json", events)

    _update_tool_call(
        tool_calls, call_id,
        status="succeeded",
        http_status=200,
        finished_at=_iso(_now()),
        result_summary={"event_id": target.get("id"), "google_event_id": target.get("google_event_id"), "calendar_id": target.get("google_calendar_id")},
        touched_calendar_event_ids=[target.get("id")],
    )

    return {"event": target, "tool_call": {"id": call_id, "status": "succeeded"}}

