        return _err("VALIDATION_ERROR", "workspace_id must match ^gws_ws_[0-9A-Z]+$")
    if not isinstance(identity_id, str) or not re.match(r"^gws_gid_[0-9A-Z]+$", identity_id or ""):
        return _err("VALIDATION_ERROR", "identity_id must match ^gws_gid_[0-9A-Z]+$")
    if not isinstance(event_id, str) or not event_id.strip():
        return _err("VALIDATION_ERROR", "event_id must be a non-empty string")
    if not isinstance(write_state, str) or write_state not in VALID_STATES:
        return _err("VALIDATION_ERROR", "write_state must be one of synced, pending_create, pending_update, pending_delete, error")
    if last_error is not None and not isinstance(last_error, str):
        return _err("VALIDATION_ERROR", "last_error must be a string or null")

    now = _now()
    workspaces = _load("workspaces.json")
    identities = _load("google_identities.json")
    events = _load("calendar_events.json")
    tool_calls = _load("tool_calls.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws or ws.get("status") == "deleted":
        return _err("NOT_FOUND", "Workspace not found")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active", workspace_status=ws.get("status"))

    ident = next((g for g in identities if g.get("id") == identity_id and g.get("workspace_id") == workspace_id), None)
    if not ident or ident.get("status") == "deleted":
        return _err("NOT_FOUND", "Identity not found")

    # quota
    quota = ws.get("daily_tool_call_quota")
    if isinstance(quota, int) and quota >= 0:
        day = _utc_day(now)
        used = _count_day_used(tool_calls, workspace_id, day)
        if used >= quota:
            call_id = _new_id("gws_call")
            tc = {
                "id": call_id,
                "workspace_id": workspace_id,
                "identity_id": identity_id,
                "tool_name": log_tool_name,
                "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "write_state": write_state, "last_error": last_error, "idempotency_key": idempotency_key},
                "idempotency_key": idempotency_key,
                "status": "failed",
                "http_status": 429,
                "error_code": "quota_exceeded",
                "error_message": "Daily tool call quota exceeded",
                "result_summary": {"quota": quota, "used": used},
                "touched_gmail_message_ids": None,
                "touched_calendar_event_ids": None,
                "started_at": _iso(now),
                "finished_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            _append_tool_call(tool_calls, tc)
            return _err("QUOTA_EXCEEDED", "Daily tool call quota exceeded", quota=quota, used=used)

    # idempotency (best-effort via tool_calls unique constraint)
    if isinstance(idempotency_key, str) and idempotency_key.strip():
        for r in tool_calls:
            if r.get("workspace_id") == workspace_id and r.get("tool_name") == log_tool_name and r.get("idempotency_key") == idempotency_key:
                if r.get("status") == "succeeded" and isinstance(r.get("result_summary"), dict) and r["result_summary"].get("event_id"):
                    ev_id = r["result_summary"]["event_id"]
                    ev = next((e for e in events if e.get("id") == ev_id and e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id), None)
                    if ev:
                        return {"event": ev, "tool_call": {"id": r.get("id"), "status": r.get("status"), "result_summary": r.get("result_summary")}}
                if r.get("status") == "failed":
                    return _err("CONFLICT", "Idempotent request previously failed", tool_call_id=r.get("id"), error_code=r.get("error_code"), error_message=r.get("error_message"))
                return _err("CONFLICT", "Idempotent request already in progress", tool_call_id=r.get("id"), status=r.get("status"))

    call_id = _new_id("gws_call")
    tc = {
        "id": call_id,
        "workspace_id": workspace_id,
        "identity_id": identity_id,
        "tool_name": log_tool_name,
        "request_params": {"workspace_id": workspace_id, "identity_id": identity_id, "event_id": event_id, "write_state": write_state, "last_error": last_error, "idempotency_key": idempotency_key},
        "idempotency_key": idempotency_key,
        "status": "running",
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "touched_gmail_message_ids": None,
        "touched_calendar_event_ids": None,
        "started_at": _iso(now),
        "finished_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _append_tool_call(tool_calls, tc)

    target = next((e for e in events if e.get("id") == event_id and e.get("workspace_id") == workspace_id and e.get("identity_id") == identity_id), None)
    if not target:
        _update_tool_call(tool_calls, call_id, status="failed", http_status=404, error_code="not_found", error_message="Event not found", finished_at=_iso(_now()))
        return _err("NOT_FOUND", "Event not found")

    cur = target.get("write_state")
    if cur not in VALID_STATES:
        cur = "synced"
        target["write_state"] = cur

    if write_state not in TRANSITIONS.get(cur, set()) and write_state != cur:
        _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="invalid_transition", error_message=f"Invalid write_state transition {cur} -> {write_state}", finished_at=_iso(_now()))
        return _err("INVALID_TRANSITION", f"Invalid write_state transition {cur} -> {write_state}")

    # CONFLICT constraints about google_event_id presence
    if write_state == "pending_create":
        if target.get("google_event_id") is not None:
            _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="conflict", error_message="Cannot set pending_create when google_event_id is already set", finished_at=_iso(_now()))
            return _err("CONFLICT", "Cannot set pending_create when google_event_id is already set")
    if write_state in ("pending_update", "pending_delete", "synced"):
        # if never created, updates/deletes don't make sense
        if target.get("google_event_id") is None and target.get("write_state") != "pending_create":
            _update_tool_call(tool_calls, call_id, status="failed", http_status=409, error_code="conflict", error_message="Cannot update/delete/sync an event without google_event_id (not yet created)", finished_at=_iso(_now()))
            return _err("CONFLICT", "Event has no google_event_id; cannot move to that state")

    target["write_state"] = write_state
    if last_error is None or (isinstance(last_error, str) and not last_error.strip()):
        target["last_error"] = None
    else:
        target["last_error"] = last_error
    target["updated_at"] = _iso(_now())
    _save("calendar_events.json", events)

    _update_tool_call(
        tool_calls, call_id,
        status="succeeded",
        http_status=200,
        finished_at=_iso(_now()),
        result_summary={"event_id": target.get("id"), "write_state": target.get("write_state")},
        touched_calendar_event_ids=[target.get("id")],
    )

    return {"event": target, "tool_call": {"id": call_id, "status": "succeeded"}}
